insert into public.admin_help_items(help_key,title_fa,body_fa,warning_fa,title_en,body_en,warning_en,active) values
('starter.overview','شروع هوشمند سایت','در شروع یک سایت جدید، RAVA بر اساس نوع سایت یک بسته محتوای نمونه کنترل‌شده می‌سازد تا پنل خالی نباشد و آموزش با مثال واقعی انجام شود.',null,'Smart site start','When a new site starts, RAVA creates a controlled archetype-aware starter pack so the admin is never empty and onboarding can use real examples.',null,true),
('starter.generate','ساخت محتوای نمونه','این عملیات فقط جاهای خالی را پر می‌کند و محتوای واقعی موجود را overwrite نمی‌کند. همه رکوردهای نمونه با Starter Marker قابل تشخیص هستند.','محتوای نمونه برای آموزش است و قبل از انتشار عمومی باید بازبینی یا جایگزین شود.','Generate starter content','This fills only missing areas and does not overwrite existing real content. Starter records are explicitly marked for later identification.','Starter content is instructional and should be reviewed or replaced before public publishing.',true)
insert into public.guidance_articles(article_key,area,route_prefix,title_fa,summary_fa,body_fa,title_en,summary_en,body_en,keywords,importance,related_help_keys,active,sort_order) values
('starter.smart_start','guidance','/admin/start','شروع هوشمند سایت','چطور سایت تازه بدون صفحه خالی بالا می‌آید','در Smart Start، راوا با توجه به نوع سایت صفحات پایه، Blockهای آموزشی، پروژه‌های نمونه و متن شروع ایجاد می‌کند. این محتوا از بسته‌های کنترل‌شده انتخاب می‌شود و تصادفی بی‌معنی نیست. اگر محتوای واقعی از قبل وجود داشته باشد، جایگزین نمی‌شود. هر Starter Record علامت‌گذاری می‌شود تا بعداً بتوان آن را از محتوای واقعی تشخیص داد.','Smart Start','How a new site starts with meaningful content','Smart Start creates archetype-aware pages, educational blocks, sample projects and starter copy. Content comes from curated controlled packs, never meaningless randomness. Existing real content is preserved and starter records are marked for later identification.',array['start','starter','onboarding','demo','شروع','نمونه','آموزش'],'important',array['starter.overview','starter.generate'],true,8)
